const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const won=n=>'₩'+Number(n||0).toLocaleString('ko-KR');
const storageGet=(key,fallback)=>{try{return localStorage.getItem(key)||fallback}catch{return fallback}};
const storageSet=(key,value)=>{try{localStorage.setItem(key,value)}catch{}};
const safeList=(k)=>{try{const v=JSON.parse(storageGet(k,'[]'));return Array.isArray(v)?v.filter(x=>typeof x==='string').slice(0,100):[]}catch{return []}};
const state={allProperties:[],compare:new Set(safeList('stayro-compare')),properties:[],sponsored:[],coupons:[],filters:{},engine:'manual',saved:new Set(safeList('stayro-saved')),city:'',q:'',activeProperty:null,adminToken:'',adminData:null,videoResults:[],conversation:null,auth:null,csrf:'',selectedPlan:'growth'};
let toastTimer;
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800)}
async function api(path,body,auth=false,chatToken=''){const options={headers:{}};if(state.csrf)options.headers['X-CSRF-Token']=state.csrf;if(chatToken)options.headers['X-Chat-Token']=chatToken;if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body)}if(auth&&state.adminToken)options.headers['X-Admin-Token']=state.adminToken;const r=await fetch(path,options);let j;try{j=await r.json()}catch{throw Error('서버 응답이 올바르지 않습니다.')};if(!r.ok)throw Error(j.error||'요청에 실패했습니다.');return j}
const imageOf=p=>p.photo_url||p.image_url||'/assets/hero.webp';
const isPublic=p=>Boolean(p.public_record);
const isAgoda=p=>p.source==='agoda'||Boolean(p.agoda_hotel_id||p.affiliate_url);
const priceLabel=p=>isAgoda(p)?'아고다에서 요금 확인':isPublic(p)?'객실 요금 확인':won(p.price)+' / 1박 · 예시';
const mapQuery=p=>encodeURIComponent(p.address||`${p.city} ${p.area} ${p.name}`);
const CATEGORY_SET=['호텔','리조트','펜션·풀빌라','한옥','게스트하우스','캠핑·글램핑'];
const CITY_SET=['','서울','부산','제주','경주','전주','가평','평창','속초','고성','강릉'];

const photoNote=p=>p.photo_url&&p.photo_license ? ('라이선스 확인 사진 · '+p.photo_license+' · '+(p.photo_author||'저작자 정보 확인')) : '인공지능 제작 분위기 이미지 · 해당 업소 실제 사진 아님';
const nav=()=>{const hash=location.hash.slice(1).split('?')[0]||'home';$$('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===hash));$('#mainNav').classList.remove('show');return hash};
function sectionTitle(k,t,sub,link='',linkTitle='전체 보기'){return `<div class="section-head"><div><span class="eyebrow">${k}</span><h2>${t}</h2><p class="section-sub">${sub}</p></div>${link?`<a class="section-link" href="#${link}">${linkTitle} ↗</a>`:''}</div>`}
function propertyCard(p){const heart=state.saved.has(p.id)?'♥':'♡';const label=p.sponsored?'광고 · 스폰서':(p.photo_url&&p.photo_license?'실제 사진 · 출처 표시':isPublic(p)?'공개자료 후보 · 업주 미인증':'인공지능 콘셉트 이미지');return `<article class="property-card" data-detail="${esc(p.id)}" tabindex="0" aria-label="${esc(p.name)} 숙소 상세"><div class="property-image"><img loading="lazy" src="${esc(imageOf(p))}" alt="${esc(p.name)} · ${esc(photoNote(p))}"><span class="property-label ${p.sponsored?'sponsor':''}">${esc(label)}</span><button class="heart" data-heart="${esc(p.id)}" aria-label="찜하기">${heart}</button></div><div class="property-copy"><div class="meta">⌖ ${esc(p.city)} · ${esc(p.area)} ${p.distance_km!==undefined?'· '+esc(p.distance_km)+' km':''}</div><h3>${esc(p.name)}</h3><p>${esc(p.category||p.tagline||'숙박시설')} ${p.address?`<small>· ${esc(p.address)}</small>`:''}</p><div class="property-tags"><span>${esc(p.category||'숙소')}</span>${(p.amenities||[]).slice(0,2).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="card-bottom"><div class="price">${esc(priceLabel(p))}</div><button type="button" class="compare-toggle" data-compare="${esc(p.id)}" aria-label="${esc(p.name)} 비교 목록 ${state.compare.has(p.id)?'해제':'추가'}" aria-pressed="${state.compare.has(p.id)}">${state.compare.has(p.id)?'✓ 비교 중':'+ 비교'}</button></div></div></article>`}
const listingGrid=p=>`<div class="property-grid">${p.map(propertyCard).join('')}</div>`;
const footer=()=>`<footer class="footer"><div class="wrap"><div class="footer-grid"><div><div class="v2-footer-logo"><img src="/assets/wordmark.svg" alt="여행갈지도 로고"></div><p>나와 맞는 숙소를 찾다.<br>여행의 영감을 발견하고, 블로그의 이야기를 만나고,<br>나에게 맞는 숙소를 찾는 인공지능 여행 큐레이션 플랫폼.</p></div><div><strong>둘러보기</strong><a href="#discover">숙소 탐색</a><a href="#map">내 주변 숙소</a><a href="#images">숙소 이미지 검색</a><a href="#journal">블로거 여행 저널</a><a href="#shorts">여행 영상</a><a href="#compare">숙소 비교</a></div><div><strong>파트너</strong><a href="#merchant">숙소 파트너 관리</a><a href="#pricing">광고 상품 안내</a><a href="#events">숙박 할인 행사</a><a href="#weekly">매주 여행 혜택</a><a href="#coupons">숙소별 기존 쿠폰</a><a href="#about">서비스 안내</a><a href="#privacy">개인정보 보호</a></div></div><div class="footer-bottom">© 2026 여행갈지도 · 공개자료 숙소 안내 · 객실 요금/재고/공식 제휴 확인 전 &nbsp; | &nbsp; 숙소별 외부 블로그·사진·영상은 소유자 권리 확인 후 게재됩니다.</div></div></footer>`;
const app=html=>{$('#app').innerHTML=html+footer();bindCommon()};
function photoMarquee(){const photos=[1,2,3,4,5,6,7,8];return `<section class="marquee-section" aria-label="인공지능 여행 콘셉트 이미지 갤러리"><div class="wrap"><span class="eyebrow">여행의 장면 · 인공지능 콘셉트 갤러리</span><h2>머무르고 싶은 순간들</h2><p class="mini-info">아래 이미지는 서로 다른 장소를 표현한 인공지능 제작 콘셉트 이미지입니다. 특정 실제 숙소를 촬영한 사진이 아닙니다.</p></div><div class="marquee-window"><div class="marquee-track">${[...photos,...photos].map((n,i)=>`<div class="marquee-photo"><img loading="lazy" src="/assets/listing-${n}.webp" alt="인공지능 생성 숙소 콘셉트 ${i+1}"><span>인공지능 콘셉트 · ${String(n).padStart(2,'0')}</span></div>`).join('')}</div></div></section>`}
